files.source.eal:
language "EAL/3"

environment lab {
  require "site" == "bench"
}

tool reader {
  version "1"
}

evidence observation {
  tool reader
  kind test
  environment lab
  max_age 60
  require "ok" == true
}

reasoning authored {
  method "structured/1"
  rationale "The measurement supports this claim."
}

claim ready {
  statement "The service is ready."
  environment lab
}

argument route = [evidence observation] via authored => ready

